<p class="muted">Để trống mật khẩu khi sửa để giữ mật khẩu hiện tại. Không thể khóa/hạ quyền quản trị viên cuối cùng.</p><?php $staff[]=['id'=>0,'name'=>'','email'=>'','role_id'=>2,'is_active'=>1];foreach($staff as $s):?><section class="panel"><h2><?= $s['id']?e($s['name']):'Thêm nhân viên mới' ?></h2><form method="post" action="/admin/staff" class="row g-3"><?= App\Core\Csrf::field() ?><input type="hidden" name="id" value="<?= $s['id'] ?>"><div class="col-md-3"><label class="form-label" for="staff-name-<?= $s['id'] ?>">Họ tên</label><input class="form-control" id="staff-name-<?= $s['id'] ?>" name="name" value="<?= e($s['name']) ?>" required></div><div class="col-md-3"><label class="form-label" for="staff-email-<?= $s['id'] ?>">Email</label><input class="form-control" id="staff-email-<?= $s['id'] ?>" name="email" type="email" value="<?= e($s['email']) ?>" required></div><div class="col-md-2"><label class="form-label" for="staff-role-<?= $s['id'] ?>">Vai trò</label><select class="form-select" id="staff-role-<?= $s['id'] ?>" name="role_id"><?php foreach($roles as $r):?><option value="<?= $r['id'] ?>" <?= $r['id']==$s['role_id']?'selected':'' ?>><?= e($r['label']) ?></option><?php endforeach?></select></div><div class="col-md-3"><label class="form-label" for="staff-pass-<?= $s['id'] ?>">Mật khẩu mới</label><input class="form-control" id="staff-pass-<?= $s['id'] ?>" name="password" type="password" minlength="10" maxlength="72" autocomplete="new-password" <?= !$s['id']?'required':'' ?>></div><div class="col-md-1"><label class="form-label d-block">Bật</label><input type="checkbox" name="is_active" value="1" aria-label="Hoạt động" <?= $s['is_active']?'checked':'' ?>></div><div><button class="btn btn-primary" type="submit"><?= $s['id']?'Lưu thay đổi':'Tạo nhân viên' ?></button></div></form></section><?php endforeach?>
